import type {Scenario,Features,FeatureName,Prediction,Provenance,StockClass} from './inventoryAI';
export type SupplyStatus='none'|'planned'|'confirmed'|'disrupted';
export type ContextScenario=Scenario&{additionalFirmQuantity:number;additionalDueDays:number|null;incomingQuantity:number;incomingEtaDays:number|null;supplyStatus:SupplyStatus};
export type ContextExperimentInput={operationId:string;scenario:ContextScenario};
export type ContextFeatureName=FeatureName|'additional_firm_quantity'|'additional_due_days'|'incoming_quantity'|'incoming_eta_days'|'supply_none'|'supply_planned'|'supply_confirmed'|'supply_disrupted';
export type ContextFeatures=Record<ContextFeatureName,number>;
export type ContextProvenance=Omit<Provenance,'evaluationKind'>&{evaluationKind:'synthetic-stock-context-prototype'};
export type ContextPrediction=Omit<Prediction,'protocol'|'features'|'outOfRange'|'evaluationKind'>&ContextProvenance&{protocol:'inventory-context-inference-2.0';features:ContextFeatures;outOfRange:ContextFeatureName[]};
export type ArtifactHashes=Pick<Prediction,'modelSha256'|'servingManifestSha256'|'datasetSha256'|'developmentSha256'|'evaluationSha256'>;
export type ContextRanges=Record<ContextFeatureName,{min:number;max:number}>;
export type ContextPredictionExpected=ArtifactHashes&{requestId:string;inputSha256:string;features:ContextFeatures;ranges:ContextRanges};
export type LegacyMetrics={accuracy:number;criticalRecall:number;observations:number;origin:'AI-authored synthetic policy'};
export type ContextMetrics=LegacyMetrics&{macroF1:number;criticalPrecision:number;families:number;accuracyInterval:[number,number]};
type HistoryBase={ownerId:string;actor:string;operationId:string;inputSha256:string;status:'Predicted'|'Unavailable';reason:{code:string;message:string}|null;createdAt:{seconds:number;nanoseconds:number};requestedAtMs:number};
export type LegacyHistoryRecord=HistoryBase&Provenance&{version:1;protocol:'inventory-synthetic-inference-1.0';scenario:Scenario;features:Features;prediction:Prediction|null;source:ArtifactHashes&{ranges:Record<FeatureName,{min:number;max:number}>;model:'RandomForest';metrics:LegacyMetrics}};
export type ContextHistoryRecord=HistoryBase&ContextProvenance&{version:2;protocol:'inventory-context-inference-2.0';scenario:ContextScenario;features:ContextFeatures;prediction:ContextPrediction|null;source:ArtifactHashes&{ranges:ContextRanges;model:'RandomForest';metrics:ContextMetrics}};
export type DemoFacts=Omit<ContextScenario,'quantityOnHand'|'reservedQuantity'|'reorderLevel'>;
export type DemoInput={operationId:string;productId:string;productVersion:number;facts:DemoFacts;dataUse:'demonstration'};
export type DemoSource={productId:string;productVersion:number;name:string;sku:string;quantityOnHand:number;reservedQuantity:number;reorderLevel:number;observedAtMs:number;dataOrigin:'demonstration-test';factsSha256:string};
export type DemoHistoryRecord=Omit<ContextHistoryRecord,'version'>&{version:3;scenarioSource:'demo-product';sourceProduct:DemoSource};
export type KnownHistory={kind:'legacy';record:LegacyHistoryRecord}|{kind:'context';record:ContextHistoryRecord}|{kind:'demo-product';record:DemoHistoryRecord}|{kind:'unsupported';reason:string};
export const INVENTORY_CONTEXT_PROTOCOL:'inventory-context-inference-2.0';
export const INVENTORY_CONTEXT_FEATURES:readonly ContextFeatureName[];
export const INVENTORY_CONTEXT_CLASSES:readonly StockClass[];
export const INVENTORY_CONTEXT_PROVENANCE:Readonly<ContextProvenance>;
export function validateContextScenario(value:unknown):ContextScenario;
export function validateContextExperimentInput(value:unknown):ContextExperimentInput;
export function contextFeaturesForScenario(value:unknown):ContextFeatures;
export function validateContextFeatures(value:unknown):ContextFeatures;
export function contextFeaturePayload(value:unknown):string;
export function validateContextPrediction(value:unknown,expected:ContextPredictionExpected):ContextPrediction;
export function validateContextHistoryRecord(value:unknown):KnownHistory;
export function validateDemoProductFacts(value:unknown):DemoFacts;
export function validateDemoProductInput(value:unknown):DemoInput;
export function validateDemoProductSource(value:unknown):DemoSource;
export function demoProductFactsPayload(value:unknown):string;
export function verifyDemoProductSource(value:unknown):Promise<DemoSource>;
export function demoScenarioFor(source:unknown,facts:unknown):ContextScenario;
export function decodeInventoryExperimentHistory(value:unknown):Promise<KnownHistory>;
